import { defineRouteMiddleware, type StarlightRouteData } from '@astrojs/starlight/route-data';
import { getEntry } from 'astro:content';
import { SITE, LABELS, pageId, localeOf, htmlPath, mdPath, isoDate, withBase } from './lib/site.mjs';

type Entry = StarlightRouteData['sidebar'][number];

/**
 * A character's archive page is hidden from the autogenerated sidebar. On the
 * character page and on the archive page it appears as a child entry right under
 * the character, so the sidebar shows where the reader is.
 */
function addArchiveEntry(sidebar: Entry[], charHref: string, entry: Entry): Entry[] {
	return sidebar.flatMap((item): Entry[] => {
		if (item.type === 'group') return [{ ...item, entries: addArchiveEntry(item.entries, charHref, entry) }];
		return item.href === charHref ? [item, entry] : [item];
	});
}

/** Adds the Markdown alternate link and JSON-LD to every page's <head>. */
export const onRequest = defineRouteMiddleware(async (context) => {
	const route = context.locals.starlightRoute;
	const { data } = route.entry;
	const id = pageId(route.entry.id);
	// Starlight's built-in 404 page has no contract fields and no Markdown twin.
	if (!data.lastVerified || !data.sources) return;

	const character = id.match(/^(?:[a-z-]+\/)?characters\/[a-z0-9-]+(?=$|\/archive$)/)?.[0];
	if (character && (await getEntry('docs', `${character}/archive`))) {
		const href = withBase(htmlPath(`${character}/archive`));
		route.sidebar = addArchiveEntry(route.sidebar, withBase(htmlPath(character)), {
			type: 'link',
			label: LABELS[localeOf(id).lang].archive,
			href,
			isCurrent: id === `${character}/archive`,
			badge: undefined,
			attrs: { 'data-child': '' },
		});
	}

	route.head.push({
		tag: 'link',
		attrs: { rel: 'alternate', type: 'text/markdown', href: SITE + mdPath(id) },
		content: '',
	});

	const jsonLd = {
		'@context': 'https://schema.org',
		'@type': 'Article',
		headline: data.title,
		description: data.description,
		inLanguage: localeOf(id).lang,
		url: SITE + htmlPath(id),
		dateModified: isoDate(data.lastVerified),
		...(data.effectiveDate ? { datePublished: isoDate(data.effectiveDate) } : {}),
		...(data.aliases?.length ? { alternativeHeadline: data.aliases.join(', ') } : {}),
		about: { '@type': 'VideoGame', name: 'Neverness to Everness', alternateName: ['NTE', '異環', '异环'] },
		citation: data.sources.map((s: { url: string }) => s.url),
		encoding: { '@type': 'MediaObject', encodingFormat: 'text/markdown', contentUrl: SITE + mdPath(id) },
	};
	route.head.push({
		tag: 'script',
		attrs: { type: 'application/ld+json' },
		content: JSON.stringify(jsonLd).replace(/</g, '\\u003c'),
	});
});
